class N {
  final int v;
  final N? left, right;
  N(this.v, [this.left, this.right]);
}

bool isBalanced(N? root) => _check(root) != -1;

int _check(N? n) {
  if (n == null) return 0;
  final l = _check(n.left);
  if (l == -1) return -1;
  final r = _check(n.right);
  if (r == -1) return -1;
  if ((l - r).abs() > 1) return -1;
  return 1 + (l > r ? l : r);
}

void main() {
  print(isBalanced(N(1, N(2), N(3))));
  print(isBalanced(N(1, N(2, N(3)))));
}
