  int v;
  B? left, right;
  B(this.v, [this.left, this.right]);
}

B? mirror(B? n) {
  if (n == null) return null;
  final tmp = n.left;
  n.left = mirror(n.right);
  n.right = mirror(tmp);
  return n;
}

